@import 'c/rlySharedStyles';

:host {
    display: block;
    --rr-blue: #0176d3;
    --rr-ink: #181818;
    --rr-muted: #5c5c5c;
    --rr-line: #e5e5e5;
}

.rr-modal .rr-modal-container { max-width: 640px; width: 92%; margin: 0 auto; position: relative; }
.rr-close { position: absolute; top: 10px; right: 10px; z-index: 1; width: 32px; height: 32px; border: 1px solid var(--rr-line); background: #fff; border-radius: 4px; }
.rr-modal-head { text-align: center; padding: 14px 48px; border-bottom: 1px solid var(--rr-line); }
.rr-modal-head h1 { margin: 0; font-size: 20px; font-weight: 400; }
.rr-modal-head p { margin-top: 4px; }
.rr-modal-body { padding: 16px 20px; display: flex; flex-direction: column; gap: 10px; color: var(--rr-ink); min-height: 120px; }
.rr-modal-foot { display: flex; justify-content: flex-end; gap: 8px; }

.rr-label { margin: 0; font-size: 12px; color: var(--rr-muted); }
.rr-kicker { margin: 0; font-size: 12px; font-weight: 700; color: #444; text-transform: uppercase; letter-spacing: 0.04em; }
.rr-head-line { margin-top: 6px; }
.rr-small { font-size: 12px; margin: 0; }
.rr-mono { font-family: ui-monospace, Menlo, Consolas, monospace; font-size: 11px; }

.rr-chips { display: flex; flex-wrap: wrap; gap: 8px; }
.rr-chip {
    display: inline-flex; align-items: center; gap: 6px; min-height: 32px; padding: 4px 14px; border-radius: 16px;
    border: 1px solid #c9c9c9; background: #fff; color: var(--rr-ink); font-size: 13px; cursor: pointer;
}
.rr-chip:focus-visible { outline: 2px solid var(--rr-blue); outline-offset: 2px; }
.rr-chip-sub { font-size: 11px; color: var(--rr-muted); }
.rr-chip-on { background: var(--rr-blue); border-color: var(--rr-blue); color: #fff; }
.rr-chip-on .rr-chip-sub { color: #fff; }
.rr-chip-off { background: #f3f3f3; color: #939393; cursor: not-allowed; border-style: dashed; }
.rr-chip-icon { --slds-c-icon-color-foreground: #fff; }

.rr-what { margin: 0; padding-left: 18px; list-style: disc; font-size: 13px; line-height: 1.5; }
.rr-snap { display: grid; grid-template-columns: 72px minmax(0, 1fr); gap: 4px 10px; margin: 0; padding: 10px 12px; border: 1px solid var(--rr-line); border-radius: 4px; background: #fafaf9; font-size: 12px; }
.rr-snap dt { color: var(--rr-muted); }
.rr-snap dd { margin: 0; overflow-wrap: anywhere; }

.rr-msg { padding: 8px 12px; border-radius: 4px; font-size: 12px; line-height: 1.45; }

.rr-seg { display: inline-flex; border: 1px solid #c9c9c9; border-radius: 4px; overflow: hidden; align-self: flex-start; }
.rr-seg-btn { border: 0; border-right: 1px solid #c9c9c9; background: #fff; color: var(--rr-blue); padding: 6px 14px; font-size: 13px; cursor: pointer; }
.rr-seg-btn:last-child { border-right: 0; }
.rr-seg-btn:focus-visible { outline: 2px solid var(--rr-blue); outline-offset: -2px; }
.rr-seg-on { background: var(--rr-blue); color: #fff; }
.rr-seg-off { color: #939393; cursor: not-allowed; }

@media (max-width: 480px) {
    .rr-modal .rr-modal-container { width: 100%; }
    .rr-modal-body { padding: 12px 16px; }
}
